import{_ as s,c as t,a,aS as p}from"./chunks/framework.BB9D2qGO.js";const e="/assets/%E6%9D%8E%E5%B0%8F%E9%BE%99.CxGdBL1C.png",o="/assets/%E6%9D%B0%E6%A3%AE%E6%96%AF%E5%9D%A6%E6%A3%AE.DLDnS19f.png",r="/assets/%E6%9D%B0%E6%A3%AE%E6%96%AF%E5%9D%A6%E6%A3%AE2.BC8gVJR_.jpg",i="/assets/%E6%88%91%E7%9A%84%E5%81%A5%E8%BA%AB9.KX2EGVR_.jpg",c="/assets/%E6%88%91%E7%9A%84%E5%81%A5%E8%BA%AB10.D1sCtOx9.jpg",E="/assets/%E6%88%91%E7%9A%84%E5%81%A5%E8%BA%AB3.YDrV2SdC.jpg",A="/assets/%E6%88%91%E7%9A%84%E5%81%A5%E8%BA%AB4.DIHoxTrq.jpg",l="/assets/%E6%88%91%E7%9A%84%E5%81%A5%E8%BA%AB5.DZf4ACqf.jpg",_="/assets/%E6%88%91%E7%9A%84%E5%81%A5%E8%BA%AB7.DmRsVopO.jpg",n="/assets/%E6%88%91%E7%9A%84%E5%81%A5%E8%BA%AB2.D0HnLm6J.jpg",m="/assets/%E6%88%91%E7%9A%84%E5%81%A5%E8%BA%AB6.Dphh7YdA.jpg",h="/assets/%E6%88%91%E7%9A%84%E5%81%A5%E8%BA%AB1.Dcd1l30M.jpg",d="/assets/%E6%88%91%E7%9A%84%E5%81%A5%E8%BA%AB8.RxbxkADd.jpg",g="/assets/%E6%88%91%E7%9A%84%E5%81%A5%E8%BA%AB11.v9tzCCoB.jpg",B="/assets/%E6%88%91%E7%9A%84%E5%81%A5%E8%BA%AB12.B0UsxUmu.jpg",u="/assets/%E6%88%91%E7%9A%84%E5%81%A5%E8%BA%AB13.B2O0cvAU.jpg",b="/assets/%E5%8A%A0%E6%B2%B91.C3sqVx1y.jpg",f="/assets/%E5%8A%A0%E6%B2%B92.CIZP25Yp.jpg",R=JSON.parse('{"title":"我的健身日记","description":"","frontmatter":{},"headers":[],"relativePath":"note/sport/我的健身日记.md","filePath":"note/sport/我的健身日记.md","lastUpdated":1753880156000}'),D={name:"note/sport/我的健身日记.md"},q=p('<h1 id="我的健身日记" tabindex="-1">我的健身日记 <a class="header-anchor" href="#我的健身日记" aria-label="Permalink to &quot;我的健身日记&quot;">​</a></h1><p>主要记录一下我的健身之路的点点滴滴</p><h2 id="偶像" tabindex="-1">偶像 <a class="header-anchor" href="#偶像" aria-label="Permalink to &quot;偶像&quot;">​</a></h2><p>我心目中神一般存在的人是李小龙。镇楼！ <img src="'+e+'" alt=""> 我想要的是那种精壮并且有爆发力的那种身材，有力量而不失美感，像健美的那种不喜欢，但是如果是像马东锡那种特壮的我也不抗拒，毕竟韩国最后一个男人，拳拳暴击。</p><p>举个例子比如，杰森斯坦森那种，这背绝了。。。 <img src="'+o+'" alt=""><img src="'+r+'" alt=""></p><h2 id="我的状态" tabindex="-1">我的状态 <a class="header-anchor" href="#我的状态" aria-label="Permalink to &quot;我的状态&quot;">​</a></h2><p>我是身高183cm，体重92kg。单纯看体重的话，挺重的，但是我感觉也不是一眼胖那种，不知道肉都跑哪了，看自己哪哪都挺细的，先搞到100kg再说。</p><p>不幸的是，左胳膊去年扭伤了，到现在已经8个月了，还没好，刚开始是胳膊伸不直也不敢用力。现在胳膊可以伸直了，但是用到胳膊肘的时候 就感觉有点小疼，就比如你拉引体，就不行，很苦恼。这玩意也没什么好的方法，只能慢慢静养了。苦逼...</p><p>下面说的是我最好时候的记录</p><ul><li>标准俯卧撑应该50个左右</li><li>标准硬拉引体应该可以做6个（不荡，手臂完全放直）</li><li>标准双杠臂屈伸12个（手臂完全下放到底）</li><li>臂围：弯臂38 直臂33</li></ul><p>背：强大的背阔肌，背牛逼，这人肯定牛逼，再差也不会差到哪去。</p><p>胸：我不喜欢健美的那种大胸，稍微鼓些就行，但一定要饱满，请参考 巅峰时期的李小龙的胸型</p><p>大臂：力量的象征</p><p>小臂：小臂超级难练，小臂越粗并且拉丝越好，小臂牛逼的人，再差也不会差到哪去。</p><p>腰：发力之根本，重要性我感觉可以排第一，主要它很少有人专门去训练腰部。</p><p>腿：下盘稳定的基础。</p><p>脖子：这个通常让人忽略，粗壮的脖子让你更加有威慑力，锁你喉都下不去手。</p><h2 id="体重" tabindex="-1">体重 <a class="header-anchor" href="#体重" aria-label="Permalink to &quot;体重&quot;">​</a></h2><p>这是2024-10-01称的 <img src="'+i+'" alt=""></p><p>这是2024-11-15称的 <img src="'+c+'" alt=""></p><h2 id="健身时间轴" tabindex="-1">健身时间轴 <a class="header-anchor" href="#健身时间轴" aria-label="Permalink to &quot;健身时间轴&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">时间周期太长了，好不容易收集到这些，之前一直散落在朋友圈，微博等不知名角落。感谢互联网，要不然全都丢了。</p><p></p></div><p>这个应该是2014年拍的，没记错的话，手里拿的是小米2s白色。为发烧而生，确实挺烧的。可以看出来，以前还是挺瘦的。 <img src="'+E+'" alt=""></p><p>这个应该是2015年大二放暑假时候让我弟拍的，这个暑假啥都没干，吃完饭没事就关屋里锻炼。一个多月的成果，有点倒三角的形态了。 当时还发了朋友圈😂 <img src="'+A+'" alt=""></p><p>这个是2016年5月份在大学宿舍阳台拍的，马上要滚蛋了，记录一下。 <img src="'+l+'" alt=""></p><p>这个是我2016年7月份在宿舍用三星note4拍的，这张拍的还挺有感觉的，当时也不知道怎么拍的，显的肩膀有点宽， 还隐约出现了腹肌，加了个滤镜感觉一下子就上来了，要么说照骗呢！ 三星手机屏幕和拍照还可以，续航和系统优化不行。当时买了个去年的旗舰，就感觉note系列的那个笔还挺好玩的，拿到手了也就那个样。 <img src="'+_+'" alt=""></p><p>这个是我2019年6月在租的小区里面拍的，刚运动完充完血，感觉自己又可以了，就拍了张。 <img src="'+n+'" alt=""></p><p>这个是我2020年10月份用华为mate30拍的，拍照清晰多了，旗舰机就是牛逼，现在2024年了，我依然还是在用这个手机。不过今年马上要换了。用快5年了，8+128 的，内存不够了。不过它依然是我心目中的神机。 <img src="'+m+'" alt=""></p><p>这个是我2023年10月在园区健身房晚上11点多拍的，之前没去过健身房，公司园区竟然有免费的健身房，体验了一把感觉挺爽的，开了 新世界的大门，因为白天人多，所以就等晚上10点多以后没人的时候骑着小电驴就去了。 <img src="'+h+'" alt=""></p><p>这个是我2024年5月份刚拍的，因为左胳膊也不敢玩，就右胳膊在家举了几组哑铃，感觉自己又行了，记录一下，看着像臂围38的样子么？ <img src="'+d+'" alt=""></p><p>上次（去年10月份）做双杠臂屈伸的时候，左胳膊肘肌腱拉伤了， 由于受伤之后前2个月没当回事，还继续每天玩，导致越来越严重，到目前为止已经8个多月了，还没好，目前现状是胳膊伸不直，一用力就疼。 决定好好休息下， 完全恢复了再说。果然健身的尽头是伤痛...</p><p>（最新）感觉再有2个月就差不多了，也正好整整一年了。再苟2个月...</p><p>2025.05.26更新。目前状态 <img src="'+g+'" alt=""><img src="'+B+'" alt=""><img src="'+u+'" alt=""></p><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>现阶段目标：2024年过年前，还有2个半月，能突破10个引体，目前可以拉4个。（手臂拉伤一年，刚好）</p><p>终极目标：解锁街健五大神技，俄挺，双力臂，顺风旗，单手引体向上，前/后水平</p><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>健身这玩意吧，不进则退，难得是坚持，不管你之前多厉害，你一年不练，该不行还是不行。</p><p>另外就是安全第一！安全第一！安全第一！</p><p>希望胳膊能够快点好起来，我要拉引体！！！ <img src="'+b+'" alt=""><img src="'+f+'" alt=""></p>',40),x=[q];function j(k,C,P,S,V,T){return a(),t("div",null,x)}const I=s(D,[["render",j]]);export{R as __pageData,I as default};
